import {matchStory,matchExport} from './match-story.js';
import {followUpMetric} from './quality-demo-metric.js';
const $=id=>document.getElementById(id),el=(tag,text)=>{const n=document.createElement(tag);if(text!=null)n.textContent=text;return n;};
const input={scenario:'wide',time:16,corrected:false,language:'en',mode:'analyst',focus:7,team:'harbor'},packet=matchStory(input),width=packet.football.record.width;
const svg=$('source-pitch'),ns='http://www.w3.org/2000/svg';function shape(tag,attrs){const n=document.createElementNS(ns,tag);for(const[k,v]of Object.entries(attrs))n.setAttribute(k,v);svg.append(n);return n;}
shape('rect',{x:1,y:1,width:103,height:66,fill:'none',stroke:'#9ac3af','stroke-width':.3});shape('line',{x1:52.5,y1:1,x2:52.5,y2:67,stroke:'#9ac3af','stroke-width':.3});shape('circle',{cx:52.5,cy:34,r:9.15,fill:'none',stroke:'#9ac3af','stroke-width':.3});
for(const [label,start,end,color]of [['Winger',width.runner_start_m,width.runner_end_m,'#ff607c'],['Defender',width.defender_start_m,width.defender_end_m,'#9ed9ff']]){shape('line',{x1:start[0],y1:start[1],x2:end[0],y2:end[1],stroke:color,'stroke-width':.7});shape('circle',{cx:start[0],cy:start[1],r:1.4,fill:'none',stroke:color,'stroke-width':.5});shape('circle',{cx:end[0],cy:end[1],r:1.5,fill:color});const t=shape('text',{x:end[0]+2,y:end[1]-2,fill:'white','font-size':2.5});t.textContent=label;}
const metric=followUpMetric(packet);for(const [value,label]of [[metric.value,'Defender lateral displacement'],[packet.football.record.net_forward_pass_gain_m.toFixed(1)+' m','Net forward pass gain']]){const d=el('div');d.append(el('strong',value),el('span',label));$('source-facts').append(d);}
function personalize(){const p=matchStory({...input,mode:$('audience').value,language:$('language').value}),mode=$('audience').value;$('audience-copy').textContent=mode==='beginner'?p.football.definition+' '+p.football.question:mode==='math'?followUpMetric(p).text:p.football.observation+' '+p.football.implication;}
$('audience').onchange=personalize;$('language').onchange=personalize;personalize();
for(const[stage,description]of [['Ingest',packet.evidence.length+' source records through the sixteen-second cutoff.'],['Interpret','Pass progression and player displacement calculated from synthetic events and coordinates.'],['Explain',packet.football.implication],['Render','A timed overlay uses the same cutoff and source references; download the output contract below.'],['Personalize','Change the concept explanation, positional reading or calculation above without changing the source.']]){const li=el('li');li.append(el('strong',stage+' — '),document.createTextNode(description));$('pipeline').append(li);}
$('export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(matchExport(input,[]),null,2)],{type:'application/json'})),a=el('a');a.href=url;a.download='btr-one-play-evidence.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
const names={analyst:'Scout',guide:'Guide',math:'Vector',reviewer:'Check',presenter:'Host'},images={analyst:'scout',guide:'guide',math:'vector',reviewer:'check',presenter:'host'};let report;
function show(round){const row=report.cases[round];if(!row)return;for(const b of document.querySelectorAll('[data-round]'))b.setAttribute('aria-pressed',String(Number(b.dataset.round)===round));$('question').textContent=row.input.question||(round?'What evidence would establish the run’s influence?':'What is happening away from the ball?');$('round-title').textContent=round?'Round two: what changes after the challenge?':'Round one: observation before explanation';$('contributions').replaceChildren();
 for(const p of row.team.posts){const card=el('article');card.className='contribution'+(p.engine==='reviewed_fallback'?' fallback':'');const h=el('header'),img=el('img');img.src='assets/'+images[p.role]+'-portrait.webp';img.alt='';const identity=el('div');identity.append(el('h3',names[p.role]),el('small',p.engine+' · cutoff '+p.cutoff+'s · revision '+p.revision));h.append(img,identity);card.append(h,el('p',p.summary));if(round===0&&['analyst','presenter'].includes(p.role)){const note=el('p','Reviewer finding: the wording about influence or effectiveness goes beyond these records. Passing the guard does not verify that interpretation.');note.className='review-finding';card.append(note);}if(p.working)card.append(el('code',p.working));if(p.caution){const limit=el('p','Limit: '+p.caution);limit.className='limit';card.append(limit);}const details=el('details');details.append(el('summary','Inspect source references'),el('p',(p.evidence_ids||[]).join(' · ')));if(p.evidence_contract?.observation)details.append(el('p','Recorded: '+p.evidence_contract.observation));card.append(details);$('contributions').append(card);}
 $('comparison-summary').textContent=`This round: crew ${row.team.requests} requests, ${(row.team.elapsed_ms/1000).toFixed(1)} seconds; baseline ${row.baseline.requests} request, ${(row.baseline.elapsed_ms/1000).toFixed(1)} seconds. Editorial guard acceptance: crew ${row.team.posts.filter(p=>p.engine==='azure_openai').length}/3, baseline ${row.baseline.accepted}/3.`;
 $('baseline').replaceChildren();$('baseline').append(el('p',`${row.baseline.accepted}/3 contributions passed the editorial guard. Only accepted contributions are shown here; the download retains rejected outputs as well.`));for(const p of row.baseline.posts||[]){const d=el('div');d.className='baseline-row';d.append(el('strong',names[p.role]||p.role),el('p',p.summary));$('baseline').append(d);}if(row.baseline.error)$('baseline').append(el('p',row.baseline.error));
}
for(const b of document.querySelectorAll('[data-round]'))b.onclick=()=>{if(report)show(Number(b.dataset.round));};
fetch('assets/btr-quality-evaluation-v51.json').then(r=>{if(!r.ok)throw Error('No recorded comparison available');return r.json();}).then(r=>{report=r;$('provenance').textContent=`Saved actual outputs · ${r.recorded_at} · ${r.policy}. No live generation on this page. Failed contributions retain their fallback labels.`;show(0);}).catch(()=>{$('provenance').textContent='The recorded comparison is unavailable. The source, calculation and localized reference explanations remain usable.';});
